<?php
require dirname(__DIR__).'/app/bootstrap.php';
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH) ?: '/';
if ($path==='/login') {
    if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $identity=trim((string)($_POST['identity']??'')); $ip=$_SERVER['REMOTE_ADDR']??''; $n=(int)one('SELECT COUNT(*) n FROM login_attempts WHERE identity=? AND ip_address=? AND attempted_at>NOW()-INTERVAL 15 MINUTE',[$identity,$ip])['n']; if ($n>=8) abort(429,'Terlalu banyak percobaan login. Coba lagi dalam 15 menit.'); $account=one('SELECT * FROM users WHERE (email=? OR username=?) AND active=1 AND archived_at IS NULL',[$identity,$identity]); if (!$account || !password_verify((string)($_POST['password']??''),$account['password_hash'])) { q('INSERT INTO login_attempts(identity,ip_address) VALUES (?,?)',[$identity,$ip]); redirect('/login','Email/username atau password salah.'); } q('DELETE FROM login_attempts WHERE identity=? AND ip_address=?',[$identity,$ip]); session_regenerate_id(true); $_SESSION['user']=['id'=>$account['id'],'name'=>$account['name'],'role'=>$account['role']]; audit('Login','user',(int)$account['id']); redirect('/'); }
    page_header('Masuk',true); echo '<div class="login-wrap"><section class="login-brand"><img src="/assets/images/logo-legalkes.png" alt="Legalkes" onerror="this.style.display=\'none\'"><h1>LEGALES PROGRESS</h1><p>Legalkes Consultant<br>PT Siwa Duta Gemilang</p><h2>Monitoring progress perizinan yang terstruktur dan transparan.</h2></section><section class="login-card"><p class="eyebrow">AKSES INTERNAL</p><h2>Selamat datang</h2><p>Masuk dengan akun pribadi Anda.</p>'; flash(); echo '<form method="post"><input type="hidden" name="_csrf" value="'.csrf().'"><label>Email atau username<input name="identity" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="primary">Masuk</button></form></section></div>'; echo '</body></html>'; exit;
}
$u=require_user();
if ($path==='/logout') { if ($_SERVER['REQUEST_METHOD']!=='POST') abort(405,'Metode tidak diizinkan.'); check_csrf(); audit('Logout'); $_SESSION=[]; session_destroy(); redirect('/login'); }
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); handle_post($path); }
if ($path==='/') dashboard();
elseif ($path==='/projects') projects_page();
elseif ($path==='/needs-update') needs_update_page();
elseif ($path==='/history') history_page();
elseif (preg_match('~^/projects/(\d+)$~',$path,$m)) project_page((int)$m[1]);
elseif ($path==='/clients') clients_page();
elseif (preg_match('~^/clients/(\d+)$~',$path,$m)) client_page((int)$m[1]);
elseif ($path==='/services') services_page();
elseif ($path==='/users') users_page();
elseif ($path==='/solvers') solvers_page();
elseif (preg_match('~^/solvers/(\d+)$~',$path,$m)) solver_detail((int)$m[1]);
elseif ($path==='/reports') reports_page();
elseif ($path==='/reports.csv') export_csv();
elseif ($path==='/notifications') notifications_page();
elseif ($path==='/audit') audit_page();
elseif ($path==='/settings') settings_page();
elseif ($path==='/profile') profile_page();
elseif (preg_match('~^/attachments/(\d+)$~',$path,$m)) download((int)$m[1]);
else abort(404,'Halaman tidak ditemukan.');
function page_header(string $title,bool $login=false): void { $u=user(); echo '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc($title).' · LEGALES PROGRESS</title><link rel="stylesheet" href="/assets/app.css"><link rel="icon" href="/assets/images/logo-legalkes.png"></head><body>'; if ($login) return; $links=['/'=>'Dashboard','/solvers'=>'Monitoring Solver','/clients'=>'Klien','/projects'=>$u['role']==='SOLVER'?'Project Saya':'Project','/needs-update'=>'Perlu Update','/history'=>'Riwayat Update','/services'=>'Layanan','/users'=>'User','/reports'=>'Laporan','/notifications'=>'Notifikasi','/audit'=>'Audit Log','/settings'=>'Pengaturan','/profile'=>'Profil']; echo '<div class="app"><aside id="sidebar"><div class="brand"><img src="/assets/images/logo-legalkes.png" alt="" onerror="this.style.display=\'none\'"><div><b>LEGALES</b><small>PROGRESS</small></div></div><nav>'; foreach ($links as $href=>$label) { if ($u['role']==='SOLVER' && in_array($href,['/solvers','/clients','/services','/users','/reports','/audit','/settings'],true)) continue; if ($u['role']!=='SOLVER' && in_array($href,['/needs-update','/history'],true)) continue; if ($u['role']==='DIREKTUR' && in_array($href,['/services','/users','/audit','/settings'],true)) continue; echo '<a class="'.(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)===$href?'active':'').'" href="'.$href.'">'.esc($label).'</a>'; } echo '</nav><div class="sidebar-foot">Legalkes Consultant<br><small>PT Siwa Duta Gemilang</small></div></aside><div class="main"><header><button class="menu" type="button" onclick="document.body.classList.toggle(\'nav-open\')">☰</button><div><strong>'.esc($title).'</strong><small>'.date('l, d M Y').' · WIB</small></div><div class="account"><span>'.esc($u['name']).'<small>'.esc($u['role']).'</small></span><form method="post" action="/logout"><input type="hidden" name="_csrf" value="'.csrf().'"><button class="ghost">Keluar</button></form></div></header><main>'; flash(); }
function page_footer(): void { echo '</main></div></div><script src="/assets/app.js"></script></body></html>'; }
function flash(): void { if (!empty($_SESSION['flash'])) { echo '<div class="flash">'.esc($_SESSION['flash']).'</div>'; unset($_SESSION['flash']); } }
function form_open(string $action): void { echo '<form method="post" action="'.esc($action).'" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="'.csrf().'">'; }
function select_input(string $name,array $options,$selected='',string $label=''): void { echo '<label>'.esc($label?:ucfirst($name)).'<select name="'.esc($name).'">'; foreach ($options as $value=>$text) echo '<option value="'.esc((string)$value).'"'.((string)$value===(string)$selected?' selected':'').'>'.esc((string)$text).'</option>'; echo '</select></label>'; }
function statuses(): array { return array_combine(['Baru','Aktif','Proses','Menunggu','Tertunda','Terbit','Selesai','Dibatalkan'],['Baru','Aktif','Proses','Menunggu','Tertunda','Terbit','Selesai','Dibatalkan']); }
function waiting(): array { return array_combine(['Tidak Ada Kendala','Menunggu Klien','Menunggu Instansi','Menunggu Internal','Menunggu Solver','Lainnya'],['Tidak Ada Kendala','Menunggu Klien','Menunggu Instansi','Menunggu Internal','Menunggu Solver','Lainnya']); }
function badge(string $text): string { $color=in_array($text,['Selesai','Terbit','TARGET TERPENUHI'],true)?'green':(in_array($text,['Menunggu','Menunggu Klien','Menunggu Instansi','HAMPIR TERPENUHI'],true)?'amber':(in_array($text,['Tertunda','BELUM ADA UPDATE','OVERDUE'],true)?'red':'blue')); return '<span class="badge '.$color.'">'.esc($text).'</span>'; }
function project_rows(string $extra='',array $params=[]): array { $sql='SELECT p.*,c.name client_name,c.pic_name,s.name service_name,u.name solver_name FROM projects p JOIN clients c ON c.id=p.client_id JOIN services s ON s.id=p.service_id JOIN users u ON u.id=p.solver_id WHERE p.archived_at IS NULL'; if (user()['role']==='SOLVER') { $sql.=' AND p.solver_id=?'; $params=array_merge([user()['id']],$params); } return all($sql.$extra,$params); }
function dashboard(): void { $rows=project_rows(' ORDER BY p.updated_at DESC'); [$start,$end]=week_bounds(); $active=array_values(array_filter($rows,fn($p)=>active_status($p['status']))); $need=count(array_filter($active,fn($p)=>$p['next_action_due_date'] && $p['next_action_due_date']<=date('Y-m-d'))); $wc=count(array_filter($active,fn($p)=>$p['waiting_status']==='Menunggu Klien')); $wi=count(array_filter($active,fn($p)=>$p['waiting_status']==='Menunggu Instansi')); $stale=count(array_filter($active,fn($p)=>strtotime($p['last_progress_update']??$p['created_at'])<=time()-7*86400)); $issued=count(array_filter($rows,fn($p)=>$p['status']==='Terbit' && str_starts_with((string)$p['tanggal_terbit'],date('Y-m')))); $done=count(array_filter($rows,fn($p)=>$p['status']==='Selesai' && str_starts_with((string)$p['tanggal_selesai'],date('Y-m')))); $counts=[]; foreach ($active as $p) $counts[$p['id']]=weekly_count((int)$p['id'],$start,$end); $target=3*count($active); $achieved=array_sum(array_map(fn($n)=>min(3,$n),$counts)); page_header('Dashboard'); echo '<div class="hero"><div><p class="eyebrow">'.esc(date('d M',strtotime($start))).' – '.esc(date('d M Y',strtotime($end.' -1 day'))).' · PERIODE BERJALAN</p><h1>'.(user()['role']==='SOLVER'?'Halo, '.esc(user()['name']):'Ringkasan operasional').'</h1><p>Pantau progres perizinan dan kewajiban komunikasi klien dalam satu tempat.</p></div><div class="hero-stat"><small>Target update klien</small><strong>'.$achieved.' <em>/ '.$target.'</em></strong><span>'.max(0,$target-$achieved).' update lagi untuk target minggu ini</span></div></div><div class="metrics">'; foreach ([['Project aktif',count($active)],['Perlu tindakan',$need],['Menunggu klien',$wc],['Menunggu instansi',$wi],['Belum update ≥7 hari',$stale],['Terbit bulan ini',$issued],['Selesai bulan ini',$done]] as [$label,$value]) echo '<div class="metric"><small>'.esc($label).'</small><strong>'.$value.'</strong></div>'; echo '</div><div class="panel"><div class="panel-head"><div><p class="eyebrow">PRIORITAS MINGGU INI</p><h2>Update klien per project</h2></div><a class="text-link" href="/projects">Lihat semua project →</a></div>'; usort($active,fn($a,$b)=>($counts[$a['id']]??0)<=>($counts[$b['id']]??0)); if (!$active) echo '<div class="empty">Belum ada project aktif.</div>'; foreach (array_slice($active,0,12) as $p) { $n=min(3,$counts[$p['id']]); echo '<a class="priority" href="/projects/'.$p['id'].'"><div><strong>'.esc($p['client_name']).'</strong><small>'.esc($p['service_name']).' · '.esc($p['solver_name']).'</small></div><div class="bar"><i style="width:'.($n/3*100).'%"></i></div><b>'.$n.'/3</b>'.badge(['BELUM ADA UPDATE','PERLU UPDATE','HAMPIR TERPENUHI','TARGET TERPENUHI'][$n]).'</a>'; } echo '</div>'; page_footer(); }
function projects_page(): void { $search=trim((string)($_GET['q']??'')); $status=$_GET['status']??''; $solverFilter=(int)($_GET['solver_id']??0); $clientFilter=(int)($_GET['client_id']??0); $serviceFilter=(int)($_GET['service_id']??0); $waitingFilter=$_GET['waiting_status']??''; $weeklyFilter=$_GET['weekly']??''; $attention=$_GET['attention']??''; $where='';$params=[]; if ($search!=='') { $where.=' AND (c.name LIKE ? OR c.pic_name LIKE ? OR p.code LIKE ? OR s.name LIKE ? OR u.name LIKE ? OR p.nomor_izin LIKE ?)'; $params=array_fill(0,6,'%'.$search.'%'); } if (isset(statuses()[$status])) { $where.=' AND p.status=?'; $params[]=$status; } if ($solverFilter && user()['role']!=='SOLVER') { $where.=' AND p.solver_id=?'; $params[]=$solverFilter; } if ($clientFilter) { $where.=' AND p.client_id=?'; $params[]=$clientFilter; } if ($serviceFilter) { $where.=' AND p.service_id=?'; $params[]=$serviceFilter; } if (isset(waiting()[$waitingFilter])) { $where.=' AND p.waiting_status=?'; $params[]=$waitingFilter; } $rows=project_rows($where.' ORDER BY p.updated_at DESC',$params); [$start,$end]=week_bounds(); $rows=array_values(array_filter($rows,function($p) use($weeklyFilter,$attention,$start,$end) { $count=min(3,weekly_count((int)$p['id'],$start,$end)); if ($weeklyFilter!=='' && (string)$count!==$weeklyFilter) return false; $days=(time()-strtotime($p['last_progress_update']??$p['created_at']))/86400; return match($attention) { 'stale3'=>$days>=3,'stale7'=>$days>=7,'overdue'=>$p['next_action_due_date'] && $p['next_action_due_date']<date('Y-m-d') && active_status($p['status']),'issued'=>$p['status']==='Terbit','completed'=>$p['status']==='Selesai',default=>true }; })); page_header(user()['role']==='SOLVER'?'Project Saya':'Project'); echo '<div class="page-title"><div><p class="eyebrow">PERIZINAN</p><h1>Project</h1></div>'.(user()['role']==='ADMIN'?'<button class="primary" data-open="new-project">+ Project baru</button>':'').'</div><form class="filters" method="get"><input name="q" placeholder="Cari klien, kode, layanan, solver..." value="'.esc($search).'">'; select_input('status',[''=>'Semua status']+statuses(),$status,''); if (user()['role']!=='SOLVER') select_input('solver_id',[''=>'Semua Solver']+array_column(all('SELECT id,name FROM users WHERE role="SOLVER" AND archived_at IS NULL ORDER BY name'),'name','id'),$solverFilter,'Solver'); select_input('client_id',[''=>'Semua klien']+array_column(all('SELECT id,name FROM clients WHERE archived_at IS NULL ORDER BY name'),'name','id'),$clientFilter,'Klien'); select_input('service_id',[''=>'Semua layanan']+array_column(all('SELECT id,name FROM services WHERE archived_at IS NULL ORDER BY name'),'name','id'),$serviceFilter,'Layanan'); select_input('waiting_status',[''=>'Semua posisi']+waiting(),$waitingFilter,'Posisi menunggu'); select_input('weekly',[''=>'Semua target','0'=>'0/3','1'=>'1/3','2'=>'2/3','3'=>'3/3'],$weeklyFilter,'Update minggu ini'); select_input('attention',[''=>'Semua indikator','stale3'=>'Belum update ≥3 hari','stale7'=>'Belum update ≥7 hari','overdue'=>'Overdue','issued'=>'Terbit','completed'=>'Selesai'],$attention,'Indikator'); echo '<button class="secondary">Terapkan</button></form><div class="panel table-wrap"><table><thead><tr><th>Project</th><th>Solver</th><th>Status</th><th>Menunggu</th><th>Update minggu ini</th><th>Next action</th></tr></thead><tbody>'; foreach ($rows as $p) { $n=weekly_count((int)$p['id'],$start,$end); echo '<tr><td><a href="/projects/'.$p['id'].'"><strong>'.esc($p['client_name']).'</strong><small>'.esc($p['code']).' · '.esc($p['service_name']).'</small></a></td><td>'.esc($p['solver_name']).'</td><td>'.badge($p['status']).'</td><td>'.esc($p['waiting_status']).'</td><td><strong>'.min(3,$n).'/3</strong></td><td>'.esc($p['next_action']?:'—').'<small>'.esc($p['next_action_due_date']?:'').'</small></td></tr>'; } echo '</tbody></table>'; if (!$rows) echo '<div class="empty">Tidak ada project sesuai pencarian.</div>'; echo '</div>'; if (user()['role']==='ADMIN') { echo '<dialog id="new-project"><h2>Project baru</h2>'; form_open('/projects'); echo '<div class="form-grid">'; select_input('client_id',array_column(all('SELECT id,name FROM clients WHERE archived_at IS NULL ORDER BY name'),'name','id'),'','Klien'); select_input('service_id',array_column(all('SELECT id,name FROM services WHERE active=1 AND archived_at IS NULL ORDER BY name'),'name','id'),'','Layanan'); select_input('solver_id',array_column(all('SELECT id,name FROM users WHERE role="SOLVER" AND active=1 AND archived_at IS NULL ORDER BY name'),'name','id'),'','Solver'); echo '<label>Tanggal mulai<input type="date" name="tanggal_mulai" value="'.date('Y-m-d').'" required></label><label>Target selesai<input type="date" name="target_selesai"></label><label>Catatan<textarea name="notes"></textarea></label></div><div class="actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary" name="action" value="create_project">Simpan project</button></div></form></dialog>'; } page_footer(); }
function project_page(int $id): void { $p=project($id); [$start,$end]=week_bounds(); $n=weekly_count($id,$start,$end); $ms=all('SELECT * FROM project_milestones WHERE project_id=? ORDER BY sort_order',[$id]); $updates=all('SELECT pu.*,u.name actor,cu.communicated_at,cu.method,cu.summary FROM progress_updates pu JOIN users u ON u.id=pu.created_by LEFT JOIN client_updates cu ON cu.progress_update_id=pu.id WHERE pu.project_id=? ORDER BY pu.update_at DESC,pu.id DESC',[$id]); $docs=all('SELECT a.*,u.name uploader FROM attachments a JOIN users u ON u.id=a.uploader_id WHERE a.project_id=? ORDER BY a.created_at DESC',[$id]); page_header('Detail project'); echo '<a class="back" href="/projects">← Semua project</a><div class="detail-hero"><div><p class="eyebrow">'.esc($p['code']).' · '.esc($p['service_name']).'</p><h1>'.esc($p['client_name']).'</h1><p>Solver '.esc($p['solver_name']).' · Mulai '.esc($p['tanggal_mulai']).'</p><div class="badges">'.badge($p['status']).badge($p['waiting_status']).'</div></div><div class="detail-progress"><small>UPDATE KLIEN MINGGU INI</small><strong>'.min(3,$n).'/3</strong><div class="bar"><i style="width:'.(min(3,$n)/3*100).'%"></i></div></div></div><div class="toolbar">'.(user()['role']!=='DIREKTUR'?'<button class="primary" data-open="progress">+ Update progress</button><button class="secondary" data-open="document">Unggah dokumen</button>':'').(user()['role']==='ADMIN'?'<button class="secondary" data-open="edit-project">Edit project / Solver</button>':'').'</div><div class="detail-grid"><section class="panel"><h2>Milestone</h2><div class="milestones">'; foreach ($ms as $m) echo '<div class="milestone '.($m['state']==='Selesai'?'done':($m['state']==='Proses'?'current':'')).'"><span>'.($m['state']==='Selesai'?'✓':$m['sort_order']).'</span><div><strong>'.esc($m['name']).'</strong><small>'.esc($m['state']).' · Bobot '.$m['weight'].'</small></div></div>'; echo '</div><div class="progress-label">Progress <strong>'.(int)$p['progress_percentage'].'%</strong></div><div class="bar"><i style="width:'.(int)$p['progress_percentage'].'%"></i></div></section><section class="panel"><h2>Tindakan berikutnya</h2><p class="action-text">'.esc($p['next_action']?:'Belum ditentukan').'</p><p>Target: <strong>'.esc($p['next_action_due_date']?:'—').'</strong> '.($p['next_action_due_date'] && $p['next_action_due_date']<date('Y-m-d') && active_status($p['status'])?badge('OVERDUE'):'').'</p><hr><h3>Informasi</h3><dl><dt>Status</dt><dd>'.esc($p['status']).'</dd><dt>Posisi menunggu</dt><dd>'.esc($p['waiting_status']).'</dd><dt>PIC klien</dt><dd>'.esc($p['client_pic']).'</dd><dt>WhatsApp</dt><dd>'.esc($p['client_whatsapp']).'</dd><dt>Email klien</dt><dd>'.esc($p['client_email']).'</dd><dt>Nomor izin</dt><dd>'.esc($p['nomor_izin']?:'—').'</dd><dt>Update terakhir</dt><dd>'.esc($p['last_progress_update']?:'—').'</dd></dl></section></div><div class="detail-grid"><section class="panel"><h2>Timeline aktivitas</h2>'; if (!$updates) echo '<div class="empty">Belum ada update progress.</div>'; foreach ($updates as $a) echo '<article class="timeline"><small>'.esc($a['update_at']).' WIB · '.esc($a['actor']).'</small><h3>'.($a['communicated_at']?'Update klien':'Update internal').'</h3><p>'.nl2br(esc($a['development'])).'</p>'.($a['obstacle']?'<p><b>Kendala:</b> '.esc($a['obstacle']).'</p>':'').($a['communicated_at']?'<p><b>'.esc($a['method']).'</b> · '.esc($a['communicated_at']).'<br>'.esc($a['summary']).'</p>':'').'</article>'; echo '</section><section class="panel"><h2>Dokumen</h2>'; if (!$docs) echo '<div class="empty">Belum ada dokumen.</div>'; foreach ($docs as $d) echo '<a class="document" href="/attachments/'.$d['id'].'"><span>▣</span><div><strong>'.esc($d['original_name']).'</strong><small>'.esc($d['category']).' · '.esc($d['uploader']).' · '.esc($d['created_at']).'</small></div>↓</a>'; echo '</section></div>'; $moves=all('SELECT h.*,a.name old_name,b.name new_name,c.name changed_name FROM project_solver_history h JOIN users a ON a.id=h.old_solver_id JOIN users b ON b.id=h.new_solver_id JOIN users c ON c.id=h.changed_by WHERE h.project_id=? ORDER BY h.created_at DESC',[$id]); if ($moves) { echo '<section class="panel"><h2>Riwayat perpindahan Solver</h2>'; foreach ($moves as $move) echo '<article class="timeline"><small>'.esc($move['created_at']).' WIB</small><p>Project dialihkan dari '.esc($move['old_name']).' ke '.esc($move['new_name']).' oleh '.esc($move['changed_name']).'.</p><p><b>Alasan:</b> '.esc($move['reason']).'</p></article>'; echo '</section>'; } if (user()['role']!=='DIREKTUR') { echo '<dialog id="progress"><h2>Update progress</h2>'; form_open('/projects/'.$id); echo '<input type="hidden" name="action" value="progress"><div class="form-grid"><label>Tanggal dan jam update<input type="datetime-local" name="update_at" value="'.date('Y-m-d\TH:i').'" required></label>'; select_input('milestone_id',array_column($ms,'name','id'),$p['current_milestone_id'],'Tahap saat ini'); select_input('status',statuses(),$p['status'],'Status project'); select_input('waiting_status',waiting(),$p['waiting_status'],'Posisi menunggu'); echo '<label class="wide">Perkembangan terbaru<textarea name="development" required></textarea></label><label>Kendala<textarea name="obstacle"></textarea></label><label>Next action<textarea name="next_action">'.esc($p['next_action']).'</textarea></label><label>Target next action<input type="date" name="next_action_due_date" value="'.esc($p['next_action_due_date']).'"></label><label>Catatan internal<textarea name="internal_notes"></textarea></label><label>Tanggal terbit<input type="date" name="tanggal_terbit"></label><label>Nomor izin<input name="nomor_izin"></label><label class="wide check"><input type="checkbox" name="to_client" value="1" id="to-client"> Update ini sudah disampaikan kepada klien</label><div id="client-fields" class="wide form-grid" hidden><label>Tanggal & jam komunikasi<input type="datetime-local" name="communicated_at"></label>'; select_input('method',array_combine(['WhatsApp','Telepon','Email','Meeting Online','Meeting Offline','Lainnya'],['WhatsApp','Telepon','Email','Meeting Online','Meeting Offline','Lainnya']),'','Metode komunikasi'); echo '<label class="wide">Ringkasan untuk klien<textarea name="summary"></textarea></label><label class="wide">Bukti komunikasi<input type="file" name="proof"></label></div></div><div class="actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary">Simpan update</button></div></form></dialog><dialog id="document"><h2>Unggah dokumen</h2>'; form_open('/projects/'.$id); echo '<input type="hidden" name="action" value="upload">'; select_input('category',array_combine(['Dokumen Klien','Dokumen Pengajuan','Bukti Komunikasi','Dokumen Revisi','Dokumen Terbit','Lainnya'],['Dokumen Klien','Dokumen Pengajuan','Bukti Komunikasi','Dokumen Revisi','Dokumen Terbit','Lainnya'])); echo '<label>Berkas (maks. 10 MB)<input type="file" name="file" required></label><div class="actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary">Unggah</button></div></form></dialog>'; } if (user()['role']==='ADMIN') { echo '<dialog id="edit-project"><h2>Edit project</h2>'; form_open('/projects/'.$id); echo '<input type="hidden" name="action" value="edit_project"><div class="form-grid">'; select_input('solver_id',array_column(all('SELECT id,name FROM users WHERE role="SOLVER" AND active=1 ORDER BY name'),'name','id'),$p['solver_id'],'Solver'); echo '<label>Alasan perpindahan Solver<textarea name="reason"></textarea></label><label>Target selesai<input type="date" name="target_selesai" value="'.esc($p['target_selesai']).'"></label><label>Catatan<textarea name="notes">'.esc($p['notes']).'</textarea></label></div><div class="actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary">Simpan</button></div></form><hr>'; form_open('/projects/'.$id); echo '<input type="hidden" name="action" value="archive_project"><button class="danger" onclick="return confirm(\'Arsipkan project ini?\')">Arsipkan project</button></form></dialog>'; } page_footer(); }
