t type="number" name="sort_order" placeholder="Urutan" min="1" required><input type="number" name="weight" value="1" min="1" required><button class="secondary">Tambah</button></div></form></details>'; form_open('/services'); echo '<input type="hidden" name="action" value="archive_service"><input type="hidden" name="id" value="'.$s['id'].'"><button class="danger small" onclick="return confirm(\'Arsipkan layanan ini?\')">Arsipkan</button></form></td></tr>'; } echo '</tbody></table></div><dialog id="service"><h2>Layanan baru</h2>'; form_open('/services'); echo '<input type="hidden" name="action" value="create_service"><label>Nama layanan<input name="name" required></label><label>Kategori<input name="category" required></label><div class="actions"><button type="button" class="secondary" data-close>Batal</button><button class="primary">Simpan</button></div></form></dialog>'; page_footer(); }
