function solvers_page(): void { role(['ADMIN','DIREKTUR']); [$start,$end]=week_bounds($_GET['week']??null); $rows=all('SELECT id,name FROM users WHERE role="SOLVER" AND archived_at IS NULL ORDER BY name'); page_header('Monitoring Solver'); echo '<div class="page-title"><div><p class="eyebrow">KINERJA OPERASIONAL</p><h1>Monitoring Solver</h1></div><form><input type="date" name="week" value="'.esc($_GET['week']??date('Y-m-d')).'"><button class="secondary">Lihat periode</button></form></div><p>Periode '.esc(substr($start,0,10)).' – '.esc(date('Y-m-d',strtotime($end.' -1 day'))).'</p><div class="panel table-wrap"><table><thead><tr><th>Solver</th><th>Project aktif</th><th>Target update</th><th>Perlu update</th></tr></thead><tbody>'; foreach ($rows as $s) { $ps=all('SELECT * FROM projects WHERE solver_id=? AND archived_at IS NULL AND project_active_at<? AND (closed_at IS NULL OR closed_at>=?)',[$s['id'],$end,$start]); $done=0;$needs=0; foreach ($ps as $p) { $n=weekly_count((int)$p['id'],$start,$end); $done+=min(3,$n); if ($n<3) $needs++; } echo '<tr><td><a href="/solvers/'.$s['id'].'"><strong>'.esc($s['name']).'</strong></a></td><td>'.count($ps).'</td><td>'.$done.'/'.(3*count($ps)).'</td><td>'.$needs.'</td></tr>'; } echo '</tbody></table></div>'; page_footer(); }
function reports_page(): void { role(['ADMIN','DIREKTUR']); $type=$_GET['type']??'weekly'; $types=['weekly'=>'Update klien mingguan','active'=>'Project aktif','per_solver'=>'Project per Solver','unmet'=>'Belum memenuhi target','waiting_client'=>'Menunggu klien','waiting_agency'=>'Menunggu instansi','stale'=>'Tidak diperbarui ≥7 hari','overdue'=>'Overdue','issued'=>'Terbit','completed'=>'Selesai','progress'=>'Riwayat progress']; page_header('Laporan'); echo '<div class="page-title"><h1>Laporan</h1><a class="primary" href="/reports.csv?type='.urlencode($type).'&week='.urlencode($_GET['week']??date('Y-m-d')).'">Export CSV</a></div><form class="filters">'; select_input('type',$types,$type,'Jenis laporan'); echo '<label>Periode minggu<input type="date" name="week" value="'.esc($_GET['week']??date('Y-m-d')).'"></label><button class="secondary">Tampilkan</button></form>'; $rows=report_data($type,$_GET['week']??date('Y-m-d')); echo '<div class="panel table-wrap"><table><thead><tr><th>Kode</th><th>Klien</th><th>Layanan</th><th>Solver</th><th>Status</th><th>Update</th><th>Keterangan</th></tr></thead><tbody>'; foreach ($rows as $r) echo '<tr><td><a href="/projects/'.$r['id'].'">'.esc($r['code']).'</a></td><td>'.esc($r['client_name']).'</td><td>'.esc($r['service_name']).'</td><td>'.esc($r['solver_name']).'</td><td>'.esc($r['status']).'</td><td>'.esc($r['weekly']).'</td><td>'.esc($r['remark']).'</td></tr>'; echo '</tbody></table>'; if (!$rows) echo '<div class="empty">Tidak ada data untuk laporan ini.</div>'; echo '</div>'; page_footer(); }
function report_data(string $type,string $day): array {
    [$start,$end]=week_bounds($day);
    if ($type==='progress') {
        $rows=all('SELECT p.id,p.code,c.name client_name,s.name service_name,u.name solver_name,pu.status,pu.update_at,pu.development FROM progress_updates pu JOIN projects p ON p.id=pu.project_id JOIN clients c ON c.id=p.client_id JOIN services s ON s.id=p.service_id JOIN users u ON u.id=pu.created_by ORDER BY pu.update_at DESC LIMIT 1000');
        foreach ($rows as &$r) { $r['weekly']='—'; $r['remark']=$r['update_at'].' · '.$r['development']; } return $rows;
    }
    $rows=project_rows($type==='per_solver'?' ORDER BY u.name,c.name':' ORDER BY p.created_at DESC'); $out=[];
    foreach ($rows as $p) { $n=weekly_count((int)$p['id'],$start,$end); $eligible=weekly_eligible($p,$start,$end); $stale=strtotime($p['last_progress_update']??$p['created_at'])<=time()-7*86400; $overdue=$p['next_action_due_date'] && $p['next_action_due_date']<date('Y-m-d') && active_status($p['status']);
        $ok=match($type) { 'active'=>active_status($p['status']),'per_solver'=>true,'unmet'=>$eligible && $n<3,'waiting_client'=>$p['waiting_status']==='Menunggu Klien','waiting_agency'=>$p['waiting_status']==='Menunggu Instansi','stale'=>$stale && active_status($p['status']),'overdue'=>$overdue,'issued'=>$p['status']==='Terbit','completed'=>$p['status']==='Selesai',default=>$eligible };
        if (!$ok) continue; $p['weekly']=min(3,$n).'/3'; $p['remark']=$p['project_active_at']>$start && $p['project_active_at']<$end?'Mulai aktif di tengah periode.':''; $out[]=$p;
    } return $out;
}
function export_csv(): void { role(['ADMIN','DIREKTUR']); $rows=report_data($_GET['type']??'weekly',$_GET['week']??date('Y-m-d')); header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="legales-laporan.csv"'); $f=fopen('php://output','w'); fwrite($f,"\xEF\xBB\xBF"); fputcsv($f,['Kode','Klien','Layanan','Solver','Status','Update','Keterangan']); foreach ($rows as $r) fputcsv($f,[$r['code'],$r['client_name'],$r['service_name'],$r['solver_name'],$r['status'],$r['weekly'],$r['remark']]); exit; }
function notifications_page(): void {
    $rows=all('SELECT n.*,p.code FROM notifications n LEFT JOIN projects p ON p.id=n.project_id WHERE n.user_id=? ORDER BY n.created_at DESC LIMIT 100',[user()['id']]);
    [$start,$end]=week_bounds(); $alerts=[];
    foreach (project_rows() as $p) { if (!active_status($p['status'])) continue; $id=(int)$p['id']; $label=$p['code'].' · '.$p['client_name']; $count=weekly_count($id,$start,$end); if ($count<3) $alerts[]=[$id,'Target update klien',min(3,$count).'/3 update minggu ini · '.$label]; if ($p['next_action_due_date'] && $p['next_action_due_date']<date('Y-m-d')) $alerts[]=[$id,'Next action overdue',$label]; if (strtotime($p['last_progress_update']??$p['created_at'])<=time()-7*86400) $alerts[]=[$id,'Project belum diperbarui ≥7 hari',$label]; }
    page_header('Notifikasi'); echo '<div class="page-title"><h1>Notifikasi</h1></div><div class="panel"><h2>Perlu perhatian</h2>';
    foreach ($alerts as [$id,$title,$body]) echo '<a class="document" href="/projects/'.$id.'"><div><strong>'.esc($title).'</strong><small>'.esc($body).'</small></div>→</a>';
    if (!$alerts) echo '<div class="empty">Tidak ada hal mendesak saat ini.</div>';
    echo '</div><div class="panel"><h2>Riwayat notifikasi</h2>';
    foreach ($rows as $n) echo '<div class="document"><div><strong>'.esc($n['title']).'</strong><small>'.esc($n['body']).' · '.esc($n['created_at']).'</small></div>'.($n['project_id']?'<a href="/projects/'.$n['project_id'].'">Buka →</a>':'').'</div>';
    if (!$rows) echo '<div class="empty">Belum ada notifikasi tersimpan.</div>'; echo '</div>'; page_footer();
}
