function download(int $id): void { $a=one('SELECT * FROM attachments WHERE id=?',[$id]); if (!$a) abort(404,'Dokumen tidak ditemukan.'); project((int)$a['project_id']); $file=dirname(__DIR__).'/storage/uploads/'.$a['internal_name']; if (!is_file($file)) abort(404,'Berkas tidak ditemukan.'); header('Content-Type: '.$a['mime_type']); header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'_',basename($a['original_name'])).'"'); header('Content-Length: '.filesize($file)); readfile($file); exit; }
function required(string $key,int $max=1000): string { $s=trim((string)($_POST[$key]??'')); if ($s==='' || mb_strlen($s)>$max) abort(422,'Kolom '. $key .' wajib diisi dan tidak boleh terlalu panjang.'); return $s; }
function optional(string $key,int $max=1000): ?string { $s=trim((string)($_POST[$key]??'')); if (mb_strlen($s)>$max) abort(422,'Kolom '.$key.' terlalu panjang.'); return $s===''?null:$s; }
function valid_date(?string $s,bool $time=false): ?string { if (!$s) return null; $format=$time?'Y-m-d\TH:i':'Y-m-d'; $d=DateTimeImmutable::createFromFormat('!'.$format,$s,new DateTimeZone('Asia/Jakarta')); if (!$d || $d->format($format)!==$s) abort(422,'Format tanggal tidak valid.'); return $d->format($time?'Y-m-d H:i:s':'Y-m-d'); }
function handle_post(string $path): never { $action=$_POST['action']??'';
    if ($path==='/projects' && $action==='create_project') { role(['ADMIN']); $client=(int)required('client_id'); $service=(int)required('service_id'); $solver=(int)required('solver_id'); if (!one('SELECT id FROM clients WHERE id=? AND archived_at IS NULL',[$client]) || !one('SELECT id FROM services WHERE id=? AND active=1 AND archived_at IS NULL',[$service]) || !one('SELECT id FROM users WHERE id=? AND role="SOLVER" AND active=1',[$solver])) abort(422,'Pilihan klien, layanan, atau Solver tidak valid.'); $start=valid_date(required('tanggal_mulai')); $target=valid_date(optional('target_selesai')); db()->beginTransaction(); try { q('INSERT INTO projects(client_id,service_id,solver_id,tanggal_mulai,project_active_at,target_selesai,notes,created_by,status) VALUES (?,?,?,?,?,?,?,? ,"Aktif")',[$client,$service,$solver,$start,$start.' 00:00:00',$target,optional('notes',10000),user()['id']]); $id=(int)db()->lastInsertId(); $code='LGL-'.date('Y').'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT); q('UPDATE projects SET code=? WHERE id=?',[$code,$id]); $ms=all('SELECT name,sort_order,weight FROM service_milestones WHERE service_id=? AND active=1 ORDER BY sort_order',[$service]); foreach ($ms as $m) q('INSERT INTO project_milestones(project_id,name,sort_order,weight) VALUES (?,?,?,?)',[$id,$m['name'],$m['sort_order'],$m['weight']]); q('INSERT INTO notifications(user_id,project_id,title,body) VALUES (?,? ,"Project baru","Anda ditugaskan untuk project '.$code.'")',[$solver,$id]); audit('Tambah project','project',$id,$code); db()->commit(); } catch(Throwable $e) { db()->rollBack(); throw $e; } redirect('/projects/'.$id,'Project berhasil dibuat.'); }
    if (preg_match('~^/projects/(\d+)$~',$path,$m)) { $id=(int)$m[1]; $p=project($id);
        if ($action==='progress') { role(['ADMIN','SOLVER']); $status=required('status'); if ($p['closed_at'] && active_status($status)) abort(422,'Project yang telah ditutup tidak dapat diaktifkan kembali.'); $wait=required('waiting_status'); if (!isset(statuses()[$status]) || !isset(waiting()[$wait])) abort(422,'Status tidak valid.'); $milestone=(int)required('milestone_id'); $steps=all('SELECT id,sort_order FROM project_milestones WHERE project_id=? ORDER BY sort_order',[$id]); $selected=null; foreach ($steps as $step) if ((int)$step['id']===$milestone) $selected=$step; if (!$selected) abort(422,'Tahap tidak valid.'); $when=valid_date(required('update_at'),true); $client=isset($_POST['to_client']); $communication=$client?valid_date(required('communicated_at'),true):null; if ($communication && ($communication<$p['project_active_at'] || $communication>date('Y-m-d H:i:s') || $communication<week_bounds()[0])) abort(422,'Tanggal komunikasi harus berada selama project aktif dan tidak boleh di masa depan.'); $method=$client?required('method'):null; if ($client && !in_array($method,['WhatsApp','Telepon','Email','Meeting Online','Meeting Offline','Lainnya'],true)) abort(422,'Metode komunikasi tidak valid.'); $summary=$client?required('summary',10000):null; $development=required('development',10000); $issued=$status==='Terbit'?valid_date(required('tanggal_terbit')):null; $number=$status==='Terbit'?required('nomor_izin',150):null; db()->beginTransaction(); try { q('INSERT INTO progress_updates(project_id,milestone_id,status,waiting_status,development,obstacle,next_action,next_action_due_date,internal_notes,update_at,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$id,$milestone,$status,$wait,$development,optional('obstacle',10000),optional('next_action',10000),valid_date(optional('next_action_due_date')),optional('internal_notes',10000),$when,user()['id']]); $updateId=(int)db()->lastInsertId(); if ($client) q('INSERT INTO client_updates(project_id,progress_update_id,communicated_at,method,summary,created_by) VALUES (?,?,?,?,?,?)',[$id,$updateId,$communication,$method,$summary,user()['id']]); foreach ($steps as $step) q('UPDATE project_milestones SET state=?,completed_at=CASE WHEN ?="Selesai" THEN COALESCE(completed_at,?) ELSE NULL END WHERE id=?',[$step['sort_order']<$selected['sort_order']?'Selesai':($step['id']==$milestone?'Proses':'Belum'),$step['sort_order']<$selected['sort_order']?'Selesai':'Belum',$when,$step['id']]); if (in_array($status,['Terbit','Selesai'],true)) q('UPDATE project_milestones SET state="Selesai",completed_at=COALESCE(completed_at,?) WHERE project_id=?',[$when,$id]); $percent=percentage($id); $closed=in_array($status,['Terbit','Selesai','Dibatalkan'],true)?($p['closed_at']?:$when):null; q('UPDATE projects SET current_milestone_id=?,progress_percentage=?,status=?,waiting_status=?,next_action=?,next_action_due_date=?,last_progress_update=?,tanggal_terbit=COALESCE(?,tanggal_terbit),tanggal_selesai=CASE WHEN ?="Selesai" THEN DATE(?) ELSE tanggal_selesai END,nomor_izin=COALESCE(?,nomor_izin),closed_at=? WHERE id=?',[$milestone,$percent,$status,$wait,optional('next_action',10000),valid_date(optional('next_action_due_date')),$when,$issued,$status,$when,$number,$closed,$id]); if ($client) upload_file($id,'Bukti Komunikasi','proof'); audit('Update progress','project',$id,$client?'Update klien':'Update internal'); if ($client) audit('Update klien','project',$id); if (in_array($status,['Terbit','Selesai'],true)) { foreach (all('SELECT id FROM users WHERE role IN ("ADMIN","DIREKTUR") AND active=1') as $person) q('INSERT INTO notifications(user_id,project_id,title,body) VALUES (?,?,?,?)',[$person['id'],$id,'Project '.$status,$p['code'].' · '.$p['client_name']]); } db()->commit(); } catch(Throwable $e) { db()->rollBack(); throw $e; } redirect($path,'Progress berhasil disimpan.'); }
        if ($action==='upload') { role(['ADMIN','SOLVER']); $category=required('category'); if (!in_array($category,['Dokumen Klien','Dokumen Pengajuan','Bukti Komunikasi','Dokumen Revisi','Dokumen Terbit','Lainnya'],true)) abort(422,'Kategori tidak valid.'); if (!upload_file($id,$category)) abort(422,'Pilih berkas.'); redirect($path,'Dokumen berhasil diunggah.'); }
        if ($action==='edit_project') { role(['ADMIN']); $solver=(int)required('solver_id'); if (!one('SELECT id FROM users WHERE id=? AND role="SOLVER" AND active=1',[$solver])) abort(422,'Solver tidak valid.'); db()->beginTransaction(); try { if ($solver!==(int)$p['solver_id']) { $reason=required('reason',2000); q('INSERT INTO project_solver_history(project_id,old_solver_id,new_solver_id,changed_by,reason) VALUES (?,?,?,?,?)',[$id,$p['solver_id'],$solver,user()['id'],$reason]); q('INSERT INTO notifications(user_id,project_id,title,body) VALUES (?,? ,"Penugasan baru",?)',[$solver,$id,$p['code'].' dialihkan kepada Anda.']); audit('Pindah Solver','project',$id,$reason); } q('UPDATE projects SET solver_id=?,target_selesai=?,notes=? WHERE id=?',[$solver,valid_date(optional('target_selesai')),optional('notes',10000),$id]); audit('Edit project','project',$id); db()->commit(); } catch(Throwable $e) { db()->rollBack(); throw $e; } redirect($path,'Project diperbarui.'); }
        if ($action==='archive_project') { role(['ADMIN']); q('UPDATE projects SET archived_at=NOW() WHERE id=?',[$id]); audit('Arsip project','project',$id); redirect('/projects','Project diarsipkan.'); }
    }
    if ($path==='/clients' || preg_match('~^/clients/(\d+)$~',$path,$m)) { role(['ADMIN']); $id=isset($m[1])?(int)$m[1]:null; if ($action==='create_client' || $action==='edit_client') { $data=[required('name',190),required('pic_name',120),optional('whatsapp',40),optional('email',190),optional('address',10000),optional('city',100),optional('npwp',60),optional('nib',60),optional('notes',10000)]; if ($data[3] && !filter_var($data[3],FILTER_VALIDATE_EMAIL)) abort(422,'Email tidak valid.'); if ($id) { q('UPDATE clients SET name=?,pic_name=?,whatsapp=?,email=?,address=?,city=?,npwp=?,nib=?,notes=? WHERE id=?',array_merge($data,[$id])); audit('Edit klien','client',$id); } else { q('INSERT INTO clients(name,pic_name,whatsapp,email,address,city,npwp,nib,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)',array_merge($data,[user()['id']])); $id=(int)db()->lastInsertId(); audit('Tambah klien','client',$id); } redirect('/clients/'.$id,'Klien berhasil disimpan.'); } if ($action==='archive_client' && $id) { if ((int)one('SELECT COUNT(*) n FROM projects WHERE client_id=? AND archived_at IS NULL',[$id])['n']) abort(422,'Arsipkan project klien terlebih dahulu.'); q('UPDATE clients SET archived_at=NOW() WHERE id=?',[$id]); audit('Arsip klien','client',$id); redirect('/clients','Klien diarsipkan.'); } }
    if ($path==='/services') { role(['ADMIN']); if ($action==='archive_service') { $id=(int)required('id'); q('UPDATE services SET archived_at=NOW(),active=0 WHERE id=?',[$id]); audit('Arsip layanan','service',$id); redirect('/services','Layanan diarsipkan.'); } if ($action==='create_service' || $action==='edit_service') { $name=required('name',150);$cat=required('category',100); if ($action==='create_service') { q('INSERT INTO services(name,category) VALUES (?,?)',[$name,$cat]); $id=(int)db()->lastInsertId(); } else { $id=(int)required('id'); q('UPDATE services SET name=?,category=?,active=? WHERE id=?',[$name,$cat,isset($_POST['active'])?1:0,$id]); } audit('Edit layanan','service',$id); redirect('/services','Layanan disimpan.'); } if ($action==='add_milestone' || $action==='edit_milestone') { $name=required('name',150);$order=max(1,(int)required('sort_order'));$weight=max(1,(int)required('weight')); if ($action==='add_milestone') { $service=(int)required('service_id'); q('INSERT INTO service_milestones(service_id,name,sort_order,weight) VALUES (?,?,?,?)',[$service,$name,$order,$weight]); $id=(int)db()->lastInsertId(); } else { $id=(int)required('id'); q('UPDATE service_milestones SET name=?,sort_order=?,weight=?,active=? WHERE id=?',[$name,$order,$weight,isset($_POST['active'])?1:0,$id]); } audit('Edit milestone','service_milestone',$id); redirect('/services','Milestone disimpan.'); } }
    if ($path==='/users') { role(['ADMIN']); if ($action==='archive_user') { $id=(int)required('id'); if ($id===(int)user()['id']) abort(422,'Akun sendiri tidak dapat diarsipkan.'); $target=one('SELECT role FROM users WHERE id=? AND archived_at IS NULL',[$id]); if (!$target) abort(404,'Pengguna tidak ditemukan.'); if ($target['role']==='ADMIN' && (int)one('SELECT COUNT(*) n FROM users WHERE role="ADMIN" AND active=1 AND archived_at IS NULL')['n']<=1) abort(422,'Admin aktif terakhir tidak dapat diarsipkan.'); if ((int)one('SELECT COUNT(*) n FROM projects WHERE solver_id=? AND archived_at IS NULL AND status NOT IN ("Terbit","Selesai","Dibatalkan")',[$id])['n']) abort(422,'Pindahkan project aktif sebelum mengarsipkan Solver.'); q('UPDATE users SET archived_at=NOW(),active=0 WHERE id=?',[$id]); audit('Arsip user','user',$id); redirect('/users','Pengguna diarsipkan.'); } if ($action==='create_user' || $action==='edit_user') { $name=required('name',120);$username=required('username',80);$email=required('email',190);$r=required('role'); if (!filter_var($email,FILTER_VALIDATE_EMAIL) || !in_array($r,['ADMIN','DIREKTUR','SOLVER'],true)) abort(422,'Email atau role tidak valid.'); $password=optional('password',255); if ($password && strlen($password)<12) abort(422,'Password minimal 12 karakter.'); if ($action==='create_user') { if (!$password) abort(422,'Password wajib diisi.'); q('INSERT INTO users(name,username,email,password_hash,role,active) VALUES (?,?,?,?,?,?)',[$name,$username,$email,password_hash($password,PASSWORD_DEFAULT),$r,isset($_POST['active'])?1:0]); $id=(int)db()->lastInsertId(); audit('Tambah user','user',$id); } else { $id=(int)required('id'); if ($id===(int)user()['id'] && (!isset($_POST['active']) || $r!=='ADMIN')) abort(422,'Akun sendiri tidak dapat dinonaktifkan atau diganti role.'); q('UPDATE users SET name=?,username=?,email=?,role=?,active=? WHERE id=?',[$name,$username,$email,$r,isset($_POST['active'])?1:0,$id]); if ($password) q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]); audit('Edit user','user',$id); } redirect('/users','Pengguna disimpan.'); } }
    if ($path==='/settings' && $action==='settings') { role(['ADMIN']); q('INSERT INTO settings(name,value) VALUES ("company_notice",?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[optional('company_notice',10000)]); audit('Pengaturan sistem'); redirect('/settings','Pengaturan disimpan.'); }
    if ($path==='/profile' && $action==='password') { $a=one('SELECT password_hash FROM users WHERE id=?',[user()['id']]); if (!password_verify(required('current'),$a['password_hash'])) abort(422,'Password saat ini salah.'); $pass=required('password'); if (strlen($pass)<12) abort(422,'Password baru minimal 12 karakter.'); q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($pass,PASSWORD_DEFAULT),user()['id']]); audit('Ubah password','user',(int)user()['id']); redirect('/profile','Password berhasil diubah.'); }
    abort(404,'Tindakan tidak ditemukan.');
}
function solver_detail(int $id): void {
    role(['ADMIN','DIREKTUR']); $solver=one('SELECT id,name FROM users WHERE id=? AND role="SOLVER" AND archived_at IS NULL',[$id]); if (!$solver) abort(404,'Solver tidak ditemukan.');
    [$start,$end]=week_bounds($_GET['week']??null); $rows=all('SELECT p.*,c.name client_name,s.name service_name FROM projects p JOIN clients c ON c.id=p.client_id JOIN services s ON s.id=p.service_id WHERE p.solver_id=? AND p.archived_at IS NULL AND p.project_active_at<? AND (p.closed_at IS NULL OR p.closed_at>=?) ORDER BY p.updated_at DESC',[$id,$end,$start]);
    $done=0; foreach ($rows as &$p) { $p['weekly']=min(3,weekly_count((int)$p['id'],$start,$end)); $done+=$p['weekly']; } unset($p);
    page_header('Monitoring Solver'); echo '<a class="back" href="/solvers">← Semua Solver</a><div class="page-title"><div><p class="eyebrow">MONITORING SOLVER</p><h1>'.esc($solver['name']).'</h1></div><form><input type="date" name="week" value="'.esc($_GET['week']??date('Y-m-d')).'"><button class="secondary">Periode</button></form></div><div class="metrics"><div class="metric"><small>Project periode ini</small><strong>'.count($rows).'</strong></div><div class="metric"><small>Update klien</small><strong>'.$done.' / '.(count($rows)*3).'</strong></div></div><div class="panel table-wrap"><table><thead><tr><th>Project</th><th>Tahap</th><th>Status</th><th>Menunggu</th><th>Update</th><th>Next action</th></tr></thead><tbody>';
    foreach ($rows as $p) { $m=$p['current_milestone_id']?one('SELECT name FROM project_milestones WHERE id=?',[$p['current_milestone_id']]):null; echo '<tr><td><a href="/projects/'.$p['id'].'"><strong>'.esc($p['client_name']).'</strong><small>'.esc($p['service_name']).' · '.esc($p['code']).'</small></a></td><td>'.esc($m['name']??'—').'</td><td>'.badge($p['status']).'</td><td>'.esc($p['waiting_status']).'</td><td>'.(int)$p['weekly'].'/3</td><td>'.esc($p['next_action']?:'—').'<small>'.esc($p['next_action_due_date']?:'').'</small></td></tr>'; }
    echo '</tbody></table>'; if (!$rows) echo '<div class="empty">Tidak ada project pada periode ini.</div>'; echo '</div>'; page_footer();
}
function needs_update_page(): void {
    role(['SOLVER']); [$start,$end]=week_bounds(); $rows=array_values(array_filter(project_rows(' ORDER BY p.updated_at DESC'),fn($p)=>active_status($p['status']) && weekly_count((int)$p['id'],$start,$end)<3)); usort($rows,fn($a,$b)=>weekly_count((int)$a['id'],$start,$end)<=>weekly_count((int)$b['id'],$start,$end));
    page_header('Perlu Update'); echo '<div class="page-title"><div><p class="eyebrow">TARGET MINGGU INI</p><h1>Perlu update klien</h1></div></div><p>Setiap project aktif perlu komunikasi klien pada tiga hari berbeda dalam minggu berjalan.</p><div class="panel">';
    foreach ($rows as $p) { $n=weekly_count((int)$p['id'],$start,$end); echo '<a class="priority" href="/projects/'.$p['id'].'"><div><strong>'.esc($p['client_name']).'</strong><small>'.esc($p['service_name']).' · '.esc($p['code']).'</small></div><div class="bar"><i style="width:'.($n/3*100).'%"></i></div><b>'.$n.'/3</b>'.badge(['BELUM ADA UPDATE','PERLU UPDATE','HAMPIR TERPENUHI'][$n]).'</a>'; }
    if (!$rows) echo '<div class="empty">Semua project aktif telah memenuhi target minggu ini.</div>'; echo '</div>'; page_footer();
}
function history_page(): void {
    role(['SOLVER']); $rows=all('SELECT pu.*,p.id project_id,p.code,c.name client_name,s.name service_name,cu.communicated_at,cu.method FROM progress_updates pu JOIN projects p ON p.id=pu.project_id JOIN clients c ON c.id=p.client_id JOIN services s ON s.id=p.service_id LEFT JOIN client_updates cu ON cu.progress_update_id=pu.id WHERE pu.created_by=? ORDER BY pu.update_at DESC LIMIT 200',[user()['id']]);
    page_header('Riwayat Update'); echo '<div class="page-title"><div><p class="eyebrow">AKTIVITAS SAYA</p><h1>Riwayat update</h1></div></div><div class="panel">';
    foreach ($rows as $r) echo '<a class="document" href="/projects/'.$r['project_id'].'"><div><strong>'.esc($r['client_name']).' · '.esc($r['service_name']).'</strong><small>'.esc($r['update_at']).' WIB · '.($r['communicated_at']?'Update klien melalui '.esc($r['method']):'Update internal').'</small><small>'.esc($r['development']).'</small></div>→</a>';
    if (!$rows) echo '<div class="empty">Belum ada update yang Anda catat.</div>'; echo '</div>'; page_footer();
}


